G[2] = (P + C + A)/3;
G[3] = (P + A + B)/3;
M[1] = (P + A)/2;
M[2] = (P + B)/2;
M[3] = (P + C)/2;

draw(A--B--C--cycle);
draw(A--P);
draw(B--P);
draw(C--P);
draw(A--M[2]);
draw(A--M[3]);
draw(G[2]--G[3]);
draw(M[2]--M[3]);

